function sparkline(values,kind='accent'){
 const hi=Math.max(...values)*1.1,lo=Math.min(...values)*.65;
 const coords=values.map((v,i)=>[i*100/(values.length-1),39-(v-lo)/(hi-lo)*34]);
 const d=curveR11(coords);
 return '<svg class="sparkline '+kind+'" viewBox="-2 -2 104 46" preserveAspectRatio="none" aria-hidden="true"><path class="sparkarea" d="'+d+' L100 43 L0 43 Z"/><path class="sparkpath" d="'+d+'"/><circle cx="100" cy="'+coords.at(-1)[1]+'" r="2.7"/></svg>'
}
