function listPage(){const cfg=routes[route],isClient=noAmount(cfg),isFin=cfg.type==='finance';const a=records[route];const active=a.filter(x=>!['Pago','Recebido','Aprovado'].includes(x.status));const action= isFin?(cfg.direction==='pay'?'Pagar':'Receber'):'Ver';const mainLabel=createLabel(cfg);return header(cfg.title,'',route==='audit'?'':btn(mainLabel,'plus','new','primary'))+ (cfg.group==='Compras'?visualPurchaseNav():tabs())+(cfg.group==='Compras'?purchaseOverview(a):((isClient||cfg.measure==='qty')?'':'<div class="kpis">'+kpi(cfg.measure==='qty'?'Quantidade total':'Total',amountText(cfg,total(route)),'wallet',a.length+' registros')+kpi('Em aberto',amountText(cfg,active.reduce((s,x)=>s+x.amount,0)),'calendar',active.length+' registros')+kpi(isFin?'Vencidos':'Aprovados',amountText(cfg,total(route,x=>x.status===(isFin?'Vencido':'Aprovado'))),isFin?'calendar':'check','No ambiente')+'</div>'))+'<div class="collectionhead"><div><h2>'+esc(VisualR09.sectionLabels[route]||'Registros')+'</h2><span class="muted">'+a.length+' no ambiente</span></div>'+layoutSwitch()+'</div><div class="toolbar"><label class="search">'+ic('search')+'<input id="list-search" aria-label="Pesquisar registros" placeholder="Pesquisar registros" value="'+esc(search)+'"></label><select class="filter" id="status-filter" aria-label="Filtrar status"><option value="">Todos os status</option>'+[...new Set(a.map(x=>x.status))].map(s=>'<option '+(s===status?'selected':'')+'>'+esc(s)+'</option>').join('')+'</select>'+iconbtn('Alternar densidade','menu','density')+iconbtn('Ordenar','down','sort')+'</div><div id="list-results">'+renderList()+'</div>'}
function renderList(){const cfg=routes[route],client=noAmount(cfg),fin=cfg.type==='finance',a=records[route]||[];let items=a.filter(x=>(!status||x.status===status)&&[x.id,x.party,x.description,x.center].join(' ').toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sortAsc?a.date.localeCompare(b.date):b.date.localeCompare(a.date));const count=items.length,max=Math.max(1,Math.ceil(count/pageSize));page=Math.min(page,max);items=items.slice((page-1)*pageSize,page*pageSize);if(recordView()!=='list'){const footer='<div class="board-pagination"><span>'+count+' registros · Página '+page+' de '+max+'</span><div class="row"><label>Itens por página <select class="filter" id="page-size"><option '+(pageSize===10?'selected':'')+'>10</option><option '+(pageSize===25?'selected':'')+'>25</option></select></label>'+iconbtn('Página anterior','back','prev',page===1?'disabled':'')+iconbtn('Próxima página','arrow','next',page===max?'disabled':'')+'</div></div>';return (recordView()==='board'?taskBoard(items):recordView()==='plan'?budgetCardsR09(items):recordView()==='stock'?stockCardsR09(items):contactsGrid(items))+footer}const actions=x=>route==='audit'?iconbtn('Ver '+x.id,'eye','view:'+x.id):iconbtn('Ver '+x.id,'eye','view:'+x.id)+iconbtn('Editar '+x.id,'edit','edit:'+x.id)+(fin&&!['Pago','Recebido'].includes(x.status)?(compact?iconbtn(cfg.direction==='pay'?'Pagar '+x.id:'Receber '+x.id,'check','settle:'+x.id):btn(cfg.direction==='pay'?'Pagar':'Receber','check','settle:'+x.id,'tonal')):(domainAction(route,x)?iconbtn('Alterar situação '+x.id,'check','transition:'+x.id):iconbtn('Mais ações '+x.id,'more','record-more:'+x.id)));const card=x=>'<article class="recordcard"><div class="record-identity"><span class="record-avatar">'+esc(initialsFor(x.party))+'</span><div class="record-name"><strong>'+esc(x.party)+'</strong><span class="muted">'+esc(x.id)+'</span></div>'+badge(x.status)+'</div><p class="record-description">'+esc(x.description)+'</p><div class="row"><span class="muted">'+date(x.date)+'</span>'+(client?'':'<span class="money">'+amountText(cfg,x.amount)+'</span>')+'</div><div class="actions">'+btn('Ver','eye','view:'+x.id)+(route==='audit'?'':btn('Editar','edit','edit:'+x.id)+(fin&&!['Pago','Recebido'].includes(x.status)?btn(cfg.direction==='pay'?'Pagar':'Receber','check','settle:'+x.id,'primary'):(domainAction(route,x)?btn('Decisão','check','transition:'+x.id,'tonal'):iconbtn('Mais ações','more','record-more:'+x.id))))+'</div></article>';return '<div class="tablewrap">'+(items.length?'<table class="'+(compact?'compact':'')+'"><thead><tr><th>Código</th><th>'+(cfg.partyLabel||(client?'Cliente':fin?'Parte':'Responsável'))+'</th><th>'+esc(cfg.descLabel||'Descrição')+'</th><th>Data</th>'+(client?'':'<th>'+ (cfg.measure==='qty'?'Quantidade':'Valor')+'</th>')+'<th>Status</th><th>Ações</th></tr></thead><tbody>'+items.map(x=>'<tr><td><strong>'+esc(x.id)+'</strong></td><td><div class="table-identity"><span class="record-avatar">'+esc(initialsFor(x.party))+'</span><strong>'+esc(x.party)+'</strong></div></td><td>'+esc(x.description)+'</td><td>'+date(x.date)+'</td>'+(client?'':'<td class="money">'+amountText(cfg,x.amount)+'</td>')+'<td>'+badge(x.status)+'</td><td class="actions">'+actions(x)+'</td></tr>').join('')+'</tbody></table><div class="cards">'+items.map(card).join('')+'</div>':'<div class="empty"><h2>Nenhum registro encontrado</h2><p>Altere os filtros ou crie um registro.</p>'+btn('Limpar filtros','filter','clear')+'</div>')+'<div class="table-footer"><span>'+count+' registros · Página '+page+' de '+max+'</span><div class="row"><label>Itens por página <select class="filter" id="page-size"><option '+(pageSize===10?'selected':'')+'>10</option><option '+(pageSize===25?'selected':'')+'>25</option></select></label>'+iconbtn('Página anterior','back','prev',page===1?'disabled':'')+iconbtn('Próxima página','arrow','next',page===max?'disabled':'')+'</div></div></div>'}
function taskBoard(items){
 const states=['Pendente','Em andamento','Concluído'];
 return '<div class="task-board">'+states.map((state,i)=>{const rows=items.filter(x=>x.status===state);return '<section class="board-column"><div class="board-head"><span class="board-state '+['amber','violet','green'][i]+'"></span><h2>'+state+'</h2><span class="board-count">'+rows.length+'</span></div>'+ (rows.length?rows.map(x=>'<article class="task-card"><div class="task-card-top">'+badge(x.status)+'<span class="muted">'+esc(x.id)+'</span></div><h3>'+esc(x.party)+'</h3><p>'+esc(x.description)+'</p><div class="task-meta"><span class="avatar">'+esc(x.center.slice(0,2).toUpperCase())+'</span><span>'+esc(x.center)+'</span><span class="spacer"></span>'+ic('calendar')+' '+date(x.date)+'</div><div class="task-actions">'+btn('Ver','eye','view:'+x.id)+ (domainAction(route,x)?btn('Avançar','arrow','transition:'+x.id,'tonal'):btn('Editar','edit','edit:'+x.id))+'</div></article>').join(''):'<div class="board-empty">Nenhuma tarefa nesta etapa</div>')+'</section>'}).join('')+'</div>'
}
function contactsGrid(items){
 return items.length?'<div class="contacts-grid">'+items.map((x,i)=>'<article class="contact-card"><div class="contact-top"><span class="contact-avatar">'+esc(x.party.split(' ').slice(0,2).map(v=>v[0]).join('').toUpperCase())+'</span>'+badge(x.status)+'</div><h3>'+esc(x.party)+'</h3><p class="muted">'+esc(x.center)+'</p><div class="contact-info"><span>'+ic('message')+esc(x.description)+'</span><span>'+ic('file')+esc(x.id)+'</span></div><div class="contact-actions">'+btn('Ver cadastro','eye','view:'+x.id)+iconbtn('Editar '+x.id,'edit','edit:'+x.id)+'</div></article>').join('')+'</div>':'<div class="empty"><h2>Nenhum registro encontrado</h2>'+btn('Limpar filtros','filter','clear')+'</div>'
}
function cash(){return header('Fluxo de caixa')+tabs()+'<div class="kpis">'+kpi('Entradas',money(total('finance-receipts')),'wallet','Previsto')+kpi('Saídas',money(total('finance-payments')),'wallet','Previsto')+kpi('Saldo',money(total('finance-receipts')-total('finance-payments')),'chart','Previsto')+'</div>'+chart()+'<section class="panel stack" style="margin-top:16px"><h2>Movimentos previstos</h2>'+[...records['finance-receipts'].map(x=>({...x,dir:'Entrada'})),...records['finance-payments'].map(x=>({...x,dir:'Saída'}))].sort((a,b)=>a.date.localeCompare(b.date)).map(x=>'<div class="summaryline"><span>'+date(x.date)+' · '+esc(x.party)+'</span><strong style="color:var(--'+(x.dir==='Entrada'?'green':'red')+')">'+(x.dir==='Entrada'?'+':'−')+money(x.amount)+'</strong></div>').join('')+'</section>'}
function chat(){const t=threads[chatIndex];return header('Mensagens')+'<section class="chat experience-chat '+(chatOpen?'opened':'')+'"><div class="conversations"><div class="conversation-header"><h2>Conversas</h2><span class="muted">'+threads.length+' equipes</span></div><label class="search">'+ic('search')+'<input id="chat-search" aria-label="Buscar conversas" placeholder="Buscar conversas"></label><div id="conversations">'+threads.map((x,i)=>'<button class="conversation '+(i===chatIndex?'active':'')+'" data-action="thread:'+i+'"><span class="avatar">'+x.initials+'</span><span class="copy"><strong>'+esc(x.name)+'</strong><span class="preview">'+esc(x.messages.at(-1)[1])+'</span></span>'+ic('chevron')+'</button>').join('')+'</div></div><div class="thread"><div class="threadhead"><button class="iconbtn mobileonly" data-action="chat-back" aria-label="Voltar">'+ic('back')+'</button><span class="avatar">'+t.initials+'</span><div class="thread-title"><strong>'+esc(t.name)+'</strong><span class="muted">Conversa de equipe</span></div><span class="spacer"></span>'+iconbtn('Informações da conversa','more','chat-info')+'</div><div class="threadbody"><div class="chat-date">Hoje</div>'+t.messages.map(([who,msg],i)=>'<div class="message-row '+(who==='me'?'mine':'')+'">'+(who==='me'?'':'<span class="message-avatar">'+t.initials+'</span>')+'<div class="bubble '+(who==='me'?'me':'')+'">'+esc(msg)+'</div></div>').join('')+'</div><form class="composer" id="composer"><input type="file" id="attachment" hidden><button type="button" class="iconbtn" aria-label="Anexar arquivo" data-action="attach">'+ic('attach')+'</button><input name="message" aria-label="Escreva uma mensagem" placeholder="Escreva uma mensagem"><button class="iconbtn" type="submit" aria-label="Enviar mensagem">'+ic('send')+'</button></form></div></section>'}
function login(){return '<div class="login"><section class="loginart"><div class="loginbrand">'+logo()+'</div><div class="loginstatement"><h1>O controle da sua empresa.<br><span>Em movimento.</span></h1><p>Finanças, compras e operações em uma experiência integrada.</p></div><div class="loginvisual" aria-hidden="true"><div class="visualorbit o1"></div><div class="visualorbit o2"></div><div class="visualorbit o3"></div><div class="visualcore">'+ic('logo')+'</div><span class="visualchip vc1">'+ic('wallet')+' Financeiro</span><span class="visualchip vc2">'+ic('cart')+' Compras</span><span class="visualchip vc3">'+ic('chart')+' Gestão</span></div><div class="loginfoot">MOVA · Gestão empresarial</div></section><section class="loginform"><div class="loginbox"><div class="loginformtop">'+logo()+iconbtn('Alterar tema',theme==='dark'?'sun':'moon','theme')+'</div><h2>Bem-vindo ao MOVA.</h2><p class="muted">Acesse o ambiente de demonstração.</p><div class="field"><label for="login-email">E-mail</label><input id="login-email" type="email" placeholder="usuario@empresa.com.br" autocomplete="off" disabled></div><div class="field"><label for="login-pass">Senha</label><input id="login-pass" type="password" placeholder="Sua senha" disabled></div>'+btn('Entrar na demonstração','arrow','login','primary')+'<p class="loginnotice">'+ic('help')+' Não é necessário informar credenciais.</p></div></section></div>'}
