function stockOverview(){const a=records['warehouse-stock'];return header('Estoque','Controle de materiais e movimentações')+tabs()+'<div class="kpis">'+kpi('Materiais catalogados',String(records['warehouse-catalog'].length),'box','Itens ativos')+kpi('Estoque mínimo',String(a.filter(x=>x.status==='Estoque mínimo').length),'box','Atenção necessária')+kpi('Entregas pendentes',String(records['warehouse-deliveries'].filter(x=>x.status==='Pendente').length),'task','Aguardando entrega')+'</div><div class="dashgrid"><section class="panel stack"><h2>Operações de estoque</h2><div class="tilegrid">'+linkTile('warehouse-catalog','Materiais e especificações')+linkTile('warehouse-stock','Saldos por localização')+linkTile('warehouse-movements','Entradas e saídas')+linkTile('warehouse-deliveries','Distribuição de materiais')+linkTile('warehouse-inventory','Contagem física')+linkTile('warehouse-reservations')+linkTile('warehouse-items')+linkTile('warehouse-custody')+linkTile('warehouse-epi')+linkTile('warehouse-forms')+linkTile('warehouse-reports')+linkTile('warehouse-settings')+'</div></section><section class="panel stack"><h2>Reposição necessária</h2>'+a.filter(x=>x.status==='Estoque mínimo').map(x=>'<button class="workitem" data-action="go:warehouse-stock"><span class="avatar">'+ic('box')+'</span><span><strong>'+esc(x.party)+'</strong><span class="muted">'+esc(x.center)+' · '+x.amount+' '+esc(x.description)+'</span></span><span class="spacer"></span>'+badge(x.status)+'</button>').join('')+'</section></div>'}
