function requestClose(){if(dialog.dataset.mode==='editor'&&editorBaseline!==null&&formFingerprint()!==editorBaseline){discardDialog.innerHTML='<div class="dialoghead"><h2 id="discard-title">Descartar alterações?</h2></div><div class="dialogbody"><p>As alterações deste formulário ainda não foram salvas.</p></div><div class="dialogfooter">'+btn('Continuar editando','','continue-edit')+btn('Descartar','','discard','primary')+'</div>';discardDialog.showModal();return}closeDialog()}
