function dispatch(a){const [k,v]=a.split(':');switch(k){
case'navigation-search':more(true);break;case'chart-mode':chartModeR11=v;chartRefreshR11();break;case'chart-point':chartSelectR11(document.querySelector('.analysis-target[data-index="'+v+'"]'));break;case'form-section':{const el=$('#editor-section-'+v),body=dialog.querySelector('.dialogbody');if(el&&body){{const heading=el.querySelector('h3')||el;const target=body.scrollTop+heading.getBoundingClientRect().top-body.getBoundingClientRect().top-12;body.scrollTo({top:Math.max(0,Math.min(target,body.scrollHeight-body.clientHeight)),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})};dialog.querySelectorAll('.editor-nav button').forEach(b=>b.removeAttribute('aria-current'));dialog.querySelector('[data-action="form-section:'+v+'"]')?.setAttribute('aria-current','true')}break;}case'view-mode':viewModes[route]=v;page=1;render();break;case'transition':transitionDialog(v);break;case'transition-confirm':applyTransition(...v.split('|'));break;case'add-item':$('#item-lines')?.insertAdjacentHTML('beforeend',itemLine());updateItems();break;case'save-prefs':{const form=$('#prefs-form');if(form&&validateDates(form)){preferences[route]=Object.values(formValues(form));toast('Preferências salvas na demonstração')}break;}case'lookup':openLookup(...v.split('|'));break;case'lookup-close':selector.close();break;case'login':signed=true;render();break;case'logout':signed=false;closeDialog();render();break;case'go':go(v);break;case'theme':theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;render();break;case'more':more();break;case'pending':showDialog(v,'<div class="empty"><h2>Em reconstrução</h2><p>Este módulo será migrado para o novo wireframe nos próximos lotes.</p></div>');break;case'close':requestClose();break;case'discard':discardDialog.close();editorBaseline=null;closeDialog();break;case'continue-edit':discardDialog.close();break;
case'new':if(route==='finance-entries'){showDialog('Tipo de lançamento','<div class="overlaynav">'+btn('Despesa','wallet','entry-create:finance-payments')+btn('Receita','wallet','entry-create:finance-receipts')+'</div>')}else editor(route);break;case'entry-create':editor(v);break;case'new-finance':editor('finance-payments');break;case'new-request':editor('purchase-requests');break;case'edit':if(route==='finance-entries'){const r=sourceRoute(v);if(r)editor(r,v)}else editor(route,v);break;case'view':summary(v);break;case'save':save();break;case'settle':{const x=records[route].find(x=>x.id===v);showDialog(routes[route].direction==='pay'?'Registrar pagamento':'Registrar recebimento','<div class="stack"><h2>'+money(x.amount)+'</h2><p>'+esc(x.party)+'</p><p class="muted">Confirme a operação demonstrativa. Nenhum valor real será movimentado.</p></div>',btn('Cancelar','','close')+btn('Confirmar','check','confirm-settle:'+v,'primary'));break}case'confirm-settle':{const x=records[route].find(x=>x.id===v);if(!x||['Pago','Recebido'].includes(x.status))return;const old=x.status;x.status=routes[route].direction==='pay'?'Pago':'Recebido';x.history??=[];x.history.push({from:old,to:x.status,note:'Baixa demonstrativa',at:new Date().toISOString()});closeDialog();render();toast('Operação registrada na demonstração');break;}case'record-more':showDialog('Mais ações','<div class="overlaynav">'+btn('Consultar código','file','record-code:'+v)+(route==='audit'?'':btn('Duplicar registro','plus','duplicate:'+v))+'</div>');break;case'record-code':showDialog('Código do registro','<div class="summary"><strong>'+esc(v)+'</strong></div>');break;case'duplicate':{const x=records[route]?.find(x=>x.id===v);if(x){const dest=route==='finance-entries'?sourceRoute(v):route;if(!dest)return;editor(dest);const form=$('#record-form');for(const [key,value] of Object.entries(x)){if(key==='id'||key==='status'||key==='items'||!form.elements[key]||typeof value==='object')continue;const el=form.elements[key];el.value=el.dataset.brDate!==undefined?date(value):value}if(itemRoutes.has(dest)){$('#item-lines').innerHTML=(x.items||[]).map(itemLine).join('');updateItems()}}break;}
case'density':compact=!compact;render();break;case'sort':sortAsc=!sortAsc;render();break;case'clear':search='';status='';page=1;render();break;case'prev':page=Math.max(1,page-1);$('#list-results').innerHTML=renderList();break;case'next':page++;$('#list-results').innerHTML=renderList();break;case'profile':showDialog('Alex Demo','<div class="stack"><div class="row"><span class="avatar">AD</span><strong>Administrador</strong></div>'+btn('Alterar tema',theme==='dark'?'sun':'moon','theme')+btn('Sair','logout','logout')+'</div>');break;case'company':showDialog('Selecionar empresa','<div class="overlaynav">'+btn('Empresa Modelo','check','select-company:0')+btn('Empresa operacional','users','select-company:1')+'</div>');break;case'select-company':company=Number(v);closeDialog();render();toast('Contexto selecionado · dados de demonstração compartilhados');break;case'notifications':showDialog('Notificações','<div class="stack"><div class="summary"><strong>Pagamento vencido</strong><span>Revise os registros financeiros.</span></div>'+btn('Contas a pagar','wallet','go:finance-payments')+'</div>');break;case'thread':chatIndex=Number(v);chatOpen=true;render();break;case'chat-back':chatOpen=false;render();break;case'chat-info':showDialog('Conversa', '<p>'+esc(threads[chatIndex].name)+'</p><p class="muted">Conversa demonstrativa.</p>');break;case'attach':$('#attachment')?.click();break;
}}
document.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(b&&!b.disabled){e.preventDefault();if(b.dataset.action==='remove-item'){b.closest('.itemline')?.remove();updateItems();return}if(b.dataset.action==='lookup-select'){const el=$('#f-'+lookupTarget);if(el)el.value=b.dataset.value;selector.close();return}dispatch(b.dataset.action)}});
document.addEventListener('input',e=>{if(e.target.id==='module-search'){$('#nav-results').innerHTML=navResults(e.target.value);return}if(e.target.hasAttribute('data-br-date')){const digits=e.target.value.replace(/\D/g,'').slice(0,8);e.target.value=digits.replace(/^(\d{2})(\d)/,'$1/$2').replace(/^(\d{2}\/\d{2})(\d)/,'$1/$2');e.target.setCustomValidity('');return}if(e.target.hasAttribute('data-item')){updateItems();return}if(e.target.id==='lookup-search'){const q=e.target.value.toLowerCase();selector.querySelectorAll('.lookup-choice').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(q));selector.querySelector('.lookup-empty').hidden=!!selector.querySelector('.lookup-choice:not([hidden])');return}if(e.target.id==='list-search'){search=e.target.value;page=1;$('#list-results').innerHTML=renderList()}if(e.target.id==='chat-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('.conversation').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(q))}});
document.addEventListener('change',e=>{if(e.target.id==='status-filter'){status=e.target.value;page=1;$('#list-results').innerHTML=renderList()}if(e.target.id==='page-size'){pageSize=Number(e.target.value);page=1;$('#list-results').innerHTML=renderList()}if(e.target.id==='chart-period'){chartRefreshR11()}if(e.target.id==='attachment'&&e.target.files[0]){threads[chatIndex].messages.push(['me','Anexo local: '+e.target.files[0].name]);render();toast('Anexo simulado, não enviado')}});
document.addEventListener('keydown',e=>{if(signed&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!dialog.open){e.preventDefault();more(true)}if(e.target.id==='module-search'&&e.key==='Enter'){e.preventDefault();$('#nav-results .nav-result')?.click()}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='record-form'){save();return}if(e.target.id==='composer'){const msg=new FormData(e.target).get('message').trim();if(msg){threads[chatIndex].messages.push(['me',msg]);render()}}});
dialog.addEventListener('close',()=>{if(!dialog.open)document.body.style.overflow=''});
render();
